    /// Declared `retryable: false`.
    pub const NOT_HEADLESS: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "git-ns/right/break-glass:notHeadless",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
